const TENCENT_SYMS=window.TENCENT_UNIVERSE.map(x=>x.symbol);const EM_SECIDS=window.EM_UNIVERSE.map(x=>x.secid);const LABELS=new Map();window.TENCENT_UNIVERSE.forEach(x=>LABELS.set(x.symbol,x));window.EM_UNIVERSE.forEach(x=>LABELS.set(x.symbol,x));function toSecid(sym){if(/^sh/.test(sym))return'1.'+sym.slice(2);if(/^(sz|bj)/.test(sym))return'0.'+sym.slice(2);if(/^hk/.test(sym))return'116.'+sym.slice(2);if(/^us/.test(sym))return'105.'+sym.slice(2);return null;}
function mergeQuotes(list,{via}){let n=0;list.forEach(q=>{const meta=LABELS.get(q.symbol);if(meta&&meta.group)q.group=meta.group;else q.group=q.group||q.market;if(meta&&meta.label)q.name=meta.label;state.quotes.set(q.symbol,q);Cache.set('q:'+q.symbol,q);if(via==='primary')state.degraded.delete(q.symbol);else state.degraded.set(q.symbol,via);n++;});return n;}
function fillFromCache(symbols){symbols.forEach(sym=>{if(state.quotes.has(sym))return;const c=Cache.raw('q:'+sym);if(!c)return;const q=Object.assign({},c.val,{cachedAt:c.at});state.quotes.set(sym,q);state.degraded.set(sym,'cache');});}
async function fetchStocks(){let fresh=0;let list=await window.TencentSource.getQuotes(TENCENT_SYMS);if(list.length){fresh+=mergeQuotes(list,{via:'primary'});const missing=TENCENT_SYMS.filter(s=>!list.some(q=>q.symbol===s));if(missing.length)fresh+=await fetchStocksBackup(missing);}else{fresh+=await fetchStocksBackup(TENCENT_SYMS);}
fillFromCache(TENCENT_SYMS);return fresh;}
async function fetchStocksBackup(symbols){const map=new Map();symbols.forEach(s=>{const id=toSecid(s);if(id)map.set(id,s);});if(!map.size)return 0;const backup=await window.EastmoneySource.getQuotes(Array.from(map.keys()));if(!backup.length)return 0;const remapped=backup.map(q=>Object.assign({},q,{symbol:map.get(q.secid)||q.symbol}));return mergeQuotes(remapped,{via:'backup'});}
async function fetchEmGroups(){let fresh=0;const list=await window.EastmoneySource.getQuotes(EM_SECIDS);if(list.length)fresh+=mergeQuotes(list,{via:'primary'});else{const sina=await window.SinaSource.getQuotes(['fx_susdcny','fx_seurusd','fx_sgbpusd','hf_GC','hf_CL','hf_SI']);const SINA_TO_EM={fx_susdcny:'EM:133.USDCNH',fx_seurusd:'EM:119.EURUSD',fx_sgbpusd:'EM:119.GBPUSD',hf_GC:'EM:101.GC00Y',hf_CL:'EM:102.CL00Y',hf_SI:'EM:101.SI00Y',};const remapped=sina.map(q=>SINA_TO_EM[q.symbol]?Object.assign({},q,{symbol:SINA_TO_EM[q.symbol]}):null).filter(Boolean);if(remapped.length)fresh+=mergeQuotes(remapped,{via:'backup'});}
fillFromCache(window.EM_UNIVERSE.map(x=>x.symbol));return fresh;}
async function fetchCrypto(){if(!CRYPTO_ON)return 0;const want=window.CRYPTO_FEATURED;let list=await window.BinanceSource.getQuotes(want);let via='primary';if(!list.length){list=await window.OkxSource.getQuotes(want);via='backup';}
let fresh=0;if(list.length)fresh+=mergeQuotes(list,{via});fillFromCache(want);return fresh;}
async function fetchWatchQuotes(){const polled=new Set([...TENCENT_SYMS,...EM_SECIDS,...window.CRYPTO_FEATURED]);const extras=[...new Set([...window.Store.watchlist.all().map(w=>w.symbol),...window.Store.portfolio.symbols(),])].filter(s=>s&&!polled.has(s));if(!extras.length){state.watchQuotes.clear();return;}
const emIds=extras.filter(s=>s.startsWith('EM:')).map(s=>s.slice(3));const tencentSyms=extras.filter(s=>/^(sh|sz|bj|hk|us)/.test(s));const cryptoSyms=CRYPTO_ON?extras.filter(s=>/USDT$/i.test(s)):[];const[em,tc,cc]=await Promise.all([emIds.length?window.EastmoneySource.getQuotes(emIds).catch(()=>[]):[],tencentSyms.length?window.TencentSource.getQuotes(tencentSyms).catch(()=>[]):[],cryptoSyms.length?window.BinanceSource.getQuotes(cryptoSyms).catch(()=>[]):[],]);const m=new Map();[...em,...tc,...cc].forEach(q=>{if(!q)return;m.set(q.symbol,q);Cache.set('q:'+q.symbol,q);state.degraded.delete(q.symbol);});state.watchQuotes=m;return m.size;}
let _faq=null;function fetchAllQuotes(){if(_faq)return _faq;_faq=(async()=>{const counts=await Promise.all([fetchStocks(),fetchEmGroups(),fetchCrypto(),fetchWatchQuotes()]);const fresh=counts.reduce((a,b)=>a+(b||0),0);if(fresh>0){state.lastUpdate=Date.now();}else{state.quotes.forEach((_q,sym)=>{if(!state.degraded.has(sym))state.degraded.set(sym,'stale');});}})().finally(()=>{_faq=null;});return _faq;}
