const TAPE_KEYS=['sh000001','sz399001','sz399006','sh000688','hkHSI','hkHSTECH','usDJI','usIXIC','usINX','EM:100.UDI','EM:133.USDCNH','EM:101.GC00Y','EM:102.CL00Y'].concat(CRYPTO_ON?['BTCUSDT']:[]);function tapeLabel(sym){const u=[...window.TENCENT_UNIVERSE,...window.EM_UNIVERSE].find(x=>x.symbol===sym);return u?u.label:sym;}
