function applyTheme(t){if(THEMES.indexOf(t)<0)t=DEFAULT_THEME;if(el.segTheme){syncSegPressed(el.segTheme,b=>b.dataset.theme===t);}
const root=document.documentElement;if(root.dataset.theme===t){syncThemeChrome(t);return;}
if(!reduceMotion()){root.classList.add('theming');clearTimeout(themeTimer);themeTimer=setTimeout(()=>root.classList.remove('theming'),450);}
root.dataset.theme=t;syncThemeChrome(t);invalidateFlashColors();renderHeatLegend();if(state.chart)window.Charts.retheme(state.chart);(state.multiCharts||[]).forEach(c=>{if(c&&c.h&&c.h!==state.chart)window.Charts.retheme(c.h);});}
function initReveal(){if(reduceMotion()||!('IntersectionObserver'in window))return;const io=new IntersectionObserver((entries)=>{entries.forEach(en=>{if(!en.isIntersecting)return;en.target.classList.add('rv-in');io.unobserve(en.target);});},{rootMargin:'0px 0px -6% 0px',threshold:0.04});document.querySelectorAll('.section, .pm-sec').forEach(node=>{node.classList.add('rv');io.observe(node);});}
