function schedule(name,fn,ms){clearTimeout(state.timers[name]);const gen=(state.scheduleGen[name]=(state.scheduleGen[name]||0)+1);const tick=async()=>{if(gen!==state.scheduleGen[name])return;if(document.hidden){state.timers[name]=setTimeout(tick,1000);return;}
try{await fn();}catch(e){}
if(gen!==state.scheduleGen[name])return;state.timers[name]=setTimeout(tick,typeof ms==='function'?ms():ms);};state.timers[name]=setTimeout(tick,typeof ms==='function'?ms():ms);}
