if(tab==='us'){const brkN=state.brk&&Array.isArray(state.brk.institutions)?state.brk.institutions.reduce((n,inst)=>n+((inst.holdings&&inst.holdings.length)||0),0):0;return`${visibleQuoteCount()} 个标的${brkN ? ' · 13F ' + brkN + ' 项持仓' : ''} · ${fetchTxt}`;}
if(tab==='hk'){const sbN=(state.southbound||[]).length;return`${visibleQuoteCount()} 个标的${sbN ? ' · 南向持仓 ' + sbN + ' 只' : ''} · ${fetchTxt}`;}
