host.dataset.moInkReady='1';host.classList.add('mo-ink-host');ink.setAttribute('data-mo-ink','1');function move(animate){var cur=host.querySelector('[role="tab"][aria-selected="true"]');if(!cur||!ink.isConnected)return;if(!el_rendered(cur))return;if(!animate)ink.classList.add('mo-ink-static');var hr=host.getBoundingClientRect();var r=cur.getBoundingClientRect();var base=ink.offsetWidth||1;var x=(r.left-hr.left)-(host.clientLeft||0)+(host.scrollLeft||0);var s=r.width/base;ink.style.setProperty('--mo-ink-x',x.toFixed(2)+'px');ink.style.setProperty('--mo-ink-s',s.toFixed(6));if(!animate){raf(function(){raf(function(){ink.classList.remove('mo-ink-static');});});}}
move(false);if(doc.fonts&&doc.fonts.ready&&doc.fonts.ready.then){doc.fonts.ready.then(function(){move(false);}).catch(function(){});}
